#include <stdio.h>

void reverse(int *x, int n) {
    int *p, *i, temp, m = (n - 1) / 2;
    p = x;
    i = x + n - 1;
    for (; p <= x + m; p++, i--) {
        temp = *p;
        *p = *i;
        *i = temp;
    }
}

int main() {
