#include <stdio.h>

// 检查右移类型
void check_shift_type() {
    int x = -1;
    if ((x >> 1) < 0)
        printf("当前系统为算术右移\n");
    else
        printf("当前系统为逻辑右移\n");
}

// 模拟算术右移（在逻辑右移系统中）
int arithmetic_right_shift(int x, int n) {
    if (x >= 0) return x >> n;
    int mask = ~((1 << (sizeof(int) * 8 - n)) - 1);
    return (x >> n) | mask;
}

// 模拟逻辑右移（在算术右移系统中）
int logical_right_shift(int x, int n) {
    unsigned int ux = (unsigned int)x;
    return (int)(ux >> n);
}

int main() {
    check_shift_type();

    int val = -16;
    printf("算术右移结果: %d\n", arithmetic_right_shift(val, 2));
    printf("逻辑右移结果: %d\n", logical_right_shift(val, 2));

    return 0;
}

