#include <stdio.h>
#include <stdlib.h>

int main() {
    FILE *fp;
    char ch;
    long total_chars = 0;
    long lines = 0;
    long spaces = 0;
    long comments = 0;
    int state = 0; // 0:普通, 1:可能注释, 2:单行注释, 3:多行注释, 4:可能结束多行

    if ((fp = fopen("source.c", "r")) == NULL) {
        printf("无法打开 source.c\n");
        exit(1);
    }

    while ((ch = fgetc(fp)) != EOF) {
        total_chars++;
        if (ch == '\n') lines++;
        if (ch == ' ') spaces++;

        // 简单的状态机处理注释统计
        if (state == 0) {
            if (ch == '/') state = 1;
        } else if (state == 1) {
            if (ch == '/') { state = 2; comments += 2; }
            else if (ch == '*') { state = 3; comments += 2; }
            else state = 0;
        } else if (state == 2) { // 单行注释 //
            comments++;
            if (ch == '\n') state = 0;
        } else if (state == 3) { // 多行注释 /*
            comments++;
            if (ch == '*') state = 4;
        } else if (state == 4) {
            comments++;
            if (ch == '/') state = 0;
            else if (ch != '*') state = 3;
        }
    }

    fclose(fp);

    printf("总行数: %ld\n", lines);
    printf("总字符数: %ld\n", total_chars);
    if (total_chars > 0) {
        printf("注释字符比例: %.2f%%\n", (float)comments / total_chars * 100);
        printf("空格比例: %.2f%%\n", (float)spaces / total_chars * 100);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main() {
    FILE *fin, *fout;
    char ch, next_ch;

    if ((fin = fopen("input.c", "r")) == NULL) {
        printf("无法打开 input.c\n");
        exit(1);
    }
    if ((fout = fopen("output.c", "w")) == NULL) {
        printf("无法创建 output.c\n");
        exit(1);
    }

    while ((ch = fgetc(fin)) != EOF) {
        if (ch == '/') {
            next_ch = fgetc(fin);
            if (next_ch == '/') { // 单行注释
                while ((ch = fgetc(fin)) != EOF && ch != '\n');
                if (ch == '\n') fputc(ch, fout);
            } else if (next_ch == '*') { // 多行注释
                char prev = 0;
                while ((ch = fgetc(fin)) != EOF) {
                    if (prev == '*' && ch == '/') break;
                    prev = ch;
                }
            } else {
                fputc(ch, fout);
                if (next_ch != EOF) fputc(next_ch, fout);
            }
        } else {
            fputc(ch, fout);
        }
    }

    fclose(fin);
    fclose(fout);
    printf("注释已删除，结果保存在 output.c\n");
    return 0;
}

