double calcScore(int scores[], int n) {
    int i;
    int max = scores[0];
    int min = scores[0];
    int sum = 0;

    for(i = 0; i < n; i++) {
        if(scores[i] > max) max = scores[i];
        if(scores[i] < min) min = scores[i];
        sum += scores[i];
    }

    // 减去最大值和最小值，剩余个数为 n-2
    return (double)(sum - max - min) / (n - 2);
}

